import numpy as np
def _sig(value, scale):
    a = np.asarray(value, dtype=float)
    b = np.concatenate([np.asarray([a.ndim, *a.shape], dtype=float), a.ravel()])
    k = np.arange(1.0, b.size + 1.0)
    return float((np.sum(np.abs(b)) + np.sum(b * np.cos(k))) / scale)
def _sigt(parts, scale):
    return float(sum((i + 1.0) * _sig(p, 1.0) for i, p in enumerate(parts)) / scale)
def _rate(ops, state, moment, amps):
    c, a, f, b, nn = ops
    u = np.array([amps[0] * np.sin(2.0 * np.pi * moment),
                  amps[1] * np.sin(4.0 * np.pi * moment)])
    return c + a @ state + f @ np.kron(state, state) + b @ u + nn @ np.kron(u, state)
n_nodes = 4
domain_length = 1.0
diffusivity = 0.005
boundary_values = np.array([0.0, 1.0])
assert np.allclose(_sigt(lifted_polynomial_operators(n_nodes, domain_length, diffusivity, boundary_values), 1e3), target)

