def layout():
    n_nodes = 4
    width = 2 * n_nodes
    ops = lifted_polynomial_operators(n_nodes, 1.0, 0.005, np.array([0.0, 1.0]))
    f = ops[2]
    nn = ops[4]
    lower = 0.0
    for p in range(width):
        for q in range(p):
            lower += float(np.sum(np.abs(f[:, p * width + q])))
    u = np.array([1.0, 0.0])
    st = np.concatenate([np.ones(n_nodes), np.zeros(n_nodes)])
    first = nn @ np.kron(u, st)
    swapped = nn @ np.kron(st, u)[:nn.shape[1]]
    return int(lower == 0.0) + 2 * int(np.max(np.abs(first - swapped)) > 1e-8)
assert np.allclose(layout(), target)

